const riskLevels = ["low", "medium", "low", "low", "low"];
const NOW = new Date().toISOString();
const crypto = require('crypto');

function genId() {
  return crypto.randomBytes(12).toString('hex') + crypto.randomBytes(8).toString('hex');
}

function escapeSql(s) {
  return s.replace(/'/g, "''");
}

async function main() {
  console.log("Seeding 2000 skills...");

  const TOTAL = 2000;
  const BASE = Math.floor(TOTAL / categories.length); // 39
  const REM = TOTAL % categories.length; // 11

  let globalIdx = 0;
  let sqlParts = [];
  let batchCount = 0;

  for (let c = 0; c < categories.length; c++) {
    const cat = categories[c];
    const count = c < REM ? BASE + 1 : BASE;
    const catTitles = titles[cat.slug] || [];

    for (let i = 0; i < count; i++) {
      const num = String(i + 1).padStart(2, '0');
      const name = `${cat.slug}-skill-${num}`;
      const slug = name;
      const title = i < catTitles.length ? catTitles[i] : `Skill Variant ${num}`;
      const risk = riskLevels[globalIdx % riskLevels.length];
      const reqApproval = risk === "medium" || risk === "high" ? 1 : 0;
      const purpose = `Performs ${title.toLowerCase()} within the ${cat.name} domain. Processes owner commands and task context to produce structured, validated outputs while adhering to safety and compliance rules.`;

      const content = `# ${title}

## Purpose
${purpose}

## When to Use
- When the ${cat.name} workflow requires ${title.toLowerCase()} functionality
- When a task in the ${cat.name.replace(' Skills','')} domain needs structured execution
- When manual ${title.toLowerCase()} processes need automation

## Steps
1. Receive the owner command and task context
2. Parse and validate input parameters
3. Execute the ${title.toLowerCase()} logic using available tools
4. Validate output against expected schema
5. Return structured result to the calling workflow

## Output Format
\`\`\`json
{
  "status": "success|failed",
  "data": {},
  "errors": [],
  "metadata": {
    "skill": "${escapeSql(title)}",
    "category": "${escapeSql(cat.name)}",
    "timestamp": "<ISO date>"
  }
}
\`\`\`

## Safety Rules
- No paid API usage without approval
- No credential access
- Owner approval required for external actions`;

      const id = genId();
      const row = `(
    '${id}',
    '${escapeSql(name)}',
    '${escapeSql(slug)}',
    '${escapeSql(cat.name)}',
    '${escapeSql(cat.slug)}',
    '${escapeSql(title)}',
    '1.0.0',
    'private',
    '${risk}',
    ${reqApproval},
    '["local_ai", "memory_read", "memory_write", "file_output"]',
    '["shell_unrestricted", "secret_read", "paid_api", "bulk_send", "dns_change", "delete_files", "public_publish"]',
    '["owner_command", "task_context"]',
    '["skill_output"]',
    '${escapeSql(purpose)}',
    '["No paid API usage without approval", "No credential access", "Owner approval required for external actions"]',
    'Standard approval required',
    'Log error and create approval request if blocked',
    '${escapeSql(content)}',
    '${NOW}',
    '${NOW}'
  )`;

      sqlParts.push(row);
      globalIdx++;

      if (sqlParts.length === 100) {
        const sql = `INSERT INTO Skill (id, name, slug, category, categorySlug, title, version, status, riskLevel, requiresApproval, allowedTools, forbiddenTools, inputs, outputs, purpose, safetyRules, approvalRules, failureHandling, content, createdAt, updatedAt) VALUES ${sqlParts.join(',')};`;
        await db.$executeRawUnsafe(sql);
        batchCount++;
        console.log(`  Batch ${batchCount}: inserted 100 skills (total: ${batchCount * 100})`);
        sqlParts = [];
      }
    }
  }

  // Insert remaining
  if (sqlParts.length > 0) {
    const sql = `INSERT INTO Skill (id, name, slug, category, categorySlug, title, version, status, riskLevel, requiresApproval, allowedTools, forbiddenTools, inputs, outputs, purpose, safetyRules, approvalRules, failureHandling, content, createdAt, updatedAt) VALUES ${sqlParts.join(',')};`;
    await db.$executeRawUnsafe(sql);
    batchCount++;
    console.log(`  Batch ${batchCount}: inserted ${sqlParts.length} skills`);
  }

  const finalCount = await db.skill.count();
  console.log(`\nDone! Total skills in database: ${finalCount}`);

  await db.$disconnect();
}

main().catch((e) => {
  console.error("Seed failed:", e);
  process.exit(1);
});